// Extract raw text from Gemini response
let rawText = $input.first().json.content.parts[0].text;

// Remove markdown code fences if present
rawText = rawText
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

// Parse JSON safely
let parsed;
try {
  parsed = JSON.parse(rawText);
} catch (e) {
  throw new Error('Invalid JSON returned from model');
}

// Get company info from original item
const companyData = $('Loop Over Items').item.json;

return {
  email: companyData.Email,
  company: companyData.Company,
  fullName: companyData['Full Name'],
  subject: parsed.subject || 'Spontaneous Application',
  body: parsed.body || '',
  rowIndex: companyData.__rowNum
};

